  "test": "import pytest
from langfuse import observe


def _spans_by_name(memory_exporter, name):
    return [s for s in memory_exporter.get_finished_spans() if s.name == name]


def test_observe_method_uses_qualified_name_when_flag_enabled(langfuse_memory_client, memory_exporter):
    class MyService:
        @observe(include_class_name=True)
        def work(self):
            return 42

    svc = MyService()
    assert svc.work() == 42

    # flush the in‑memory client so spans are exported
    langfuse_memory_client.flush()

    spans = _spans_by_name(memory_exporter, "MyService.work")
    assert len(spans) == 1, "Span should be recorded with the qualified method name"
